css_custom_properties_template:
/* Dark Theme Default (Control Room) */
:root {
  --font-heading: 'Anybody', 'Helvetica Neue', sans-serif;
  --font-body: 'Hanken Grotesk', system-ui, sans-serif;
  --font-mono: 'Martian Mono', monospace;

  --bg-root: #0b0f17;
  --bg-surface: #131924;
  --bg-surface-hover: #1c2433;
  --bg-surface-alt: #17202e;
  --border: #283548;
  --border-subtle: #1e293b;

  --text-main: #f1f5f9;
  --text-muted: #94a3b8;
  --text-dim: #64748b;

  --accent-primary: #38bdf8;
  --accent-primary-hover: #0ea5e9;
  --accent-primary-light: #0c4a6e;

  --status-clear: #10b981;
  --status-clear-bg: #022c22;
  --status-clear-border: #065f46;

  --status-attention: #f59e0b;
  --status-attention-bg: #451a03;
  --status-attention-border: #78350f;

  --status-critical: #ef4444;
  --status-critical-bg: #450a0a;
  --status-critical-border: #7f1d1d;

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-pill: 9999px;

  --shadow-card: 0 4px 20px -2px rgba(0, 0, 0, 0.5);
  --shadow-dropdown: 0 10px 25px -5px rgba(0, 0, 0, 0.6);
}

/* Light Theme Override */
[data-theme="light"] {
  --bg-root: #f8fafc;
  --bg-surface: #ffffff;
  --bg-surface-hover: #f1f5f9;
  --bg-surface-alt: #e2e8f0;
  --border: #cbd5e1;
  --border-subtle: #e2e8f0;

  --text-main: #0f172a;
  --text-muted: #475569;
  --text-dim: #64748b;

  --accent-primary: #0284c7;
  --accent-primary-hover: #0369a1;
  --accent-primary-light: #e0f2fe;

  --status-clear: #059669;
  --status-clear-bg: #ecfdf5;
  --status-clear-border: #a7f3d0;

  --status-attention: #d97706;
  --status-attention-bg: #fffbeb;
  --status-attention-border: #fde68a;

  --status-critical: #dc2626;
  --status-critical-bg: #fef2f2;
  --status-critical-border: #fecaca;

  --shadow-card: 0 4px 12px -2px rgba(0, 0, 0, 0.08);
  --shadow-dropdown: 0 10px 25px -5px rgba(0, 0, 0, 0.15);
}
